 /**
  * Validates and resolves an asset request path against the base public directory.
  * Prevents path traversal vulnerabilities where requested paths resolve outside
  * the configured asset root directory.
  */
 export function resolveAssetPath(directory: string, requestPath: string): string | null {
   let decodedPath: string;
   try {
     decodedPath = decodeURIComponent(requestPath);
   } catch {
     return null;
   }

   const absoluteDirectory = path.resolve(directory);
   const absoluteFilePath = path.resolve(absoluteDirectory, "." + decodedPath);

   // Ensure the resolved path remains strictly within the base directory
   const relativePath = path.relative(absoluteDirectory, absoluteFilePath);
   if (relativePath.startsWith("..") || path.isAbsolute(relativePath)) {
     return null;
   }

   return absoluteFilePath;
 }

